package cn.local.rainreminder;
import java.time.*;import java.time.temporal.ChronoUnit;import java.text.Normalizer;import java.util.*;import java.util.regex.*;
final class ScheduleDates {
 static Set<MonthDay> columnParts(String raw){Set<MonthDay> out=new HashSet<>();String text=Normalizer.normalize(raw,Normalizer.Form.NFKC).replaceAll("\\s+","").replaceAll("(?:星期|周)[一二三四五六日天]","");Matcher tokens=Pattern.compile("[0-9]+(?:[/月.\\-][0-9]+)?").matcher(text);while(tokens.find()){String token=tokens.group();if(token.matches("[0-9]+[/月.\\-][0-9]+")){String[] pair=token.split("[/月.\\-]");try{out.add(MonthDay.of(Integer.parseInt(pair[0]),Integer.parseInt(pair[1])));}catch(Exception ignored){}continue;}for(int length=1;length<=2;length++){if(token.length()<=length)continue;for(int skip=0;skip<=1;skip++){int at=length+skip;if(at>=token.length()||token.length()-at>2)continue;if(skip==1&&token.charAt(length)!='1'&&token.charAt(length)!='7')continue;try{out.add(MonthDay.of(Integer.parseInt(token.substring(0,length)),Integer.parseInt(token.substring(at))));}catch(Exception ignored){}}}}return out;}
 static LocalDate columns(String[] raw,LocalDate today){List<Set<MonthDay>> parts=new ArrayList<>();int count=0;for(String value:raw){Set<MonthDay> parsed=columnParts(value);parts.add(parsed);if(!parsed.isEmpty())count++;}if(count<3)return null;LocalDate nearest=null;long distance=Long.MAX_VALUE;for(int column=0;column<Math.min(7,parts.size());column++)for(MonthDay part:parts.get(column))for(int year=today.getYear()-1;year<=today.getYear()+1;year++){if(!part.isValidYear(year))continue;LocalDate week=part.atYear(year).minusDays(column);if(week.getDayOfWeek()!=DayOfWeek.MONDAY)continue;boolean valid=true;for(int i=0;i<Math.min(7,parts.size());i++)if(!parts.get(i).isEmpty()&&!parts.get(i).contains(MonthDay.from(week.plusDays(i)))){valid=false;break;}long gap=Math.abs(ChronoUnit.DAYS.between(today,week));if(valid&&gap<=183&&gap<distance){nearest=week;distance=gap;}}return nearest;}
 static LocalDate monday(LocalDate d){return d.minusDays(d.getDayOfWeek().getValue()-1);}
 static LocalDate read(String raw,LocalDate today){
  if(raw==null)return null;String text=Normalizer.normalize(raw,Normalizer.Form.NFKC).replaceAll("\\s+"," ").replaceAll("\\s*([-/.年月日])\\s*","$1").replace('／','/').replace('－','-').replace('—','-').replace('–','-');text=text.replaceAll("(?<=\\d)(?=20\\d{2}[-/.年])"," ");
  Pattern full=Pattern.compile("(?<!\\d)(20\\d{2})[-/.年](\\d{1,2})[-/.月](\\d{1,2})(?!\\d)");Matcher matches=full.matcher(text);Set<LocalDate> weeks=new HashSet<>();boolean invalid=false;
  while(matches.find())try{weeks.add(monday(LocalDate.of(Integer.parseInt(matches.group(1)),Integer.parseInt(matches.group(2)),Integer.parseInt(matches.group(3)))));}catch(Exception e){invalid=true;}
  if(invalid||weeks.size()>1)return null;
  String remaining=full.matcher(text).replaceAll(" ");Matcher shortDates=Pattern.compile("(?<![\\d:/.-])(\\d{1,2})[/月.-](\\d{1,2})(?![\\d:])").matcher(remaining);Set<MonthDay> parts=new HashSet<>();while(shortDates.find())try{parts.add(MonthDay.of(Integer.parseInt(shortDates.group(1)),Integer.parseInt(shortDates.group(2))));}catch(Exception e){invalid=true;}
  if(invalid)return null;if(weeks.size()==1){LocalDate week=weeks.iterator().next();return fits(parts,week)?week:null;}if(parts.isEmpty())return null;
  LocalDate nearest=null;long gap=Long.MAX_VALUE;for(MonthDay part:parts)for(int year=today.getYear()-1;year<=today.getYear()+1;year++){if(!part.isValidYear(year))continue;LocalDate date=part.atYear(year);if(parts.size()==1&&date.getDayOfWeek()!=DayOfWeek.MONDAY)continue;LocalDate week=monday(date);long distance=Math.abs(ChronoUnit.DAYS.between(today,week));if(distance<=183&&distance<gap&&fits(parts,week)){nearest=week;gap=distance;}}
  return nearest;
 }
 static boolean fits(Set<MonthDay> parts,LocalDate week){for(MonthDay part:parts){boolean found=false;for(int i=0;i<7;i++)if(MonthDay.from(week.plusDays(i)).equals(part)){found=true;break;}if(!found)return false;}return true;}
}
